const visual = {
  prepare: function (input) {
    return [{ kind: 'text', payload: '3:1' }];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var x0 = w * 0.12;
    var x1 = w * 0.88;
    var y = h * 0.66;
    var split = x0 + (x1 - x0) * 0.75;

    var segment = visualSdk.polyline([[x0, y], [x1, y]]);
    var leftTick = visualSdk.polyline([[x0, y - 12], [x0, y + 12]]);
    var splitTick = visualSdk.polyline([[split, y - 18], [split, y + 18]]);
    var rightTick = visualSdk.polyline([[x1, y - 12], [x1, y + 12]]);

    var bracketY = h * 0.44;
    var bracket = visualSdk.polyline([
      [x0, bracketY + 10],
      [x0, bracketY],
      [x1, bracketY],
      [x1, bracketY + 10]
    ]);

    var labelX = (x0 + x1) / 2;
    var labelY = bracketY - 12;

    return {
      schemaVersion: 1,
      sceneId: 'ratio-segment',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'segment', commands: segment },
        { id: 'leftTick', commands: leftTick },
        { id: 'splitTick', commands: splitTick },
        { id: 'rightTick', commands: rightTick },
        { id: 'bracket', commands: bracket }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'segment', stroke: '#1f2d3d', strokeWidth: 4, fill: 'none' },
          { type: 'path', pathId: 'leftTick', stroke: '#1f2d3d', strokeWidth: 3, fill: 'none' },
          { type: 'path', pathId: 'splitTick', stroke: '#1f2d3d', strokeWidth: 4, fill: 'none' },
          { type: 'path', pathId: 'rightTick', stroke: '#1f2d3d', strokeWidth: 3, fill: 'none' },
          { type: 'path', pathId: 'bracket', stroke: '#1f2d3d', strokeWidth: 2, fill: 'none' },
          {
            type: 'label',
            id: 'ratioLabel',
            text: '3:1',
            x: labelX,
            y: labelY,
            fontSize: 24,
            fontWeight: 600,
            fontFamily: 'sans-serif',
            textAnchor: 'middle',
            fill: '#1f2d3d'
          }
        ]
      }
    };
  }
};
